# Run from the package directory with R ineq 0.2-13 installed.
# This writes frozen tests; FPM itself does not require R.
library(ineq)
stopifnot(as.character(packageVersion('ineq')) == '0.2.13')
options(digits = 17)
lines <- c('! SPDX-License-Identifier: GPL-2.0-only OR GPL-3.0-only',
  '! Generated by validation/generate_reference.R with R ineq 0.2-13.',
  'program test_r_reference', '   use ineq_api', '   use test_support',
  '   use, intrinsic :: ieee_arithmetic, only : ieee_value, ieee_quiet_nan, ieee_positive_inf, ieee_negative_inf',
  '   implicit none', '   real(dp) :: nan, inf, neginf',
  '   real(dp), allocatable :: values(:)', '   type(lorenz_curve) :: curve',
  '   logical :: dominates', '   integer :: status',
  '   nan = ieee_value(0.0_dp, ieee_quiet_nan)',
  '   inf = ieee_value(0.0_dp, ieee_positive_inf)',
  '   neginf = ieee_value(0.0_dp, ieee_negative_inf)')
records <- list()
fnum <- function(x) {
  if (is.na(x)) return('nan')
  if (is.infinite(x)) return(if (x > 0) 'inf' else 'neginf')
  paste0(sprintf('%.17e', x), '_dp')
}
fvec <- function(x) paste0('[real(dp) :: ', paste(vapply(x, fnum, ''), collapse = ', '), ']')
# Wrap generated free-form lines without splitting strings or numeric tokens.
append <- function(text) {
  for (line in text) {
    while (nchar(line) > 122) {
      chars <- gregexpr(', ', substr(line, 1, 118), fixed = TRUE)[[1]]
      cut <- tail(chars[chars > 0], 1)
      if (!length(cut)) break
      lines <<- c(lines, paste0(substr(line, 1, cut), ' &'))
      line <- paste0('      ', substr(line, cut + 2, nchar(line)))
    }
    lines <<- c(lines, line)
  }
}
scalar <- function(expr, expected, label) {
  # R's raw power/exponential formulas lose precision near singular parameters.
  tolerance <- if (grepl('a (1e-06|0.999999|1.000001)$', label)) ', tolerance=5.0e-9_dp' else ''
  append(paste0('   call check(', expr, ', ', fnum(expected), ", '", label, "'", tolerance, ')'))
  records[[length(records) + 1L]] <<- data.frame(case = label, value = sprintf('%.17g', expected))
}
vector <- function(expr, expected, label) {
  append(paste0('   values = ', expr))
  append(paste0('   call check_array(values, ', fvec(expected), ", '", label, "')"))
  for (i in seq_along(expected)) records[[length(records) + 1L]] <<-
    data.frame(case = paste0(label, '[', i, ']'), value = sprintf('%.17g', expected[i]))
}
samples <- list(positive = c(1, 2, 4, 8), zero = c(0, 0, 1, 4), equal = rep(5, 4),
  signed = c(-2, -1, 3, 7), negative = c(-8, -4, -2, -1), single = 2,
  zero_total = c(-2, 0, 2), all_zero = c(0, 0), missing = c(1, NA, 2, NaN, 8))
spec <- list(Gini = c('gini'), RS = 'rs', Atkinson = 'atkinson', Theil = 'theil',
  Kolm = 'kolm', 'var.coeff' = 'var_coeff', entropy = 'entropy',
  Herfindahl = 'herfindahl', Rosenbluth = 'rosenbluth')
for (nm in names(samples)) {
  x <- samples[[nm]]
  for (fun in names(spec)) {
    ans <- suppressWarnings(do.call(fun, list(x)))
    scalar(paste0(spec[[fun]], '(', fvec(x), ')'), ans, paste(nm, fun))
    if (anyNA(x)) scalar(paste0(spec[[fun]], '(', fvec(x), ', na_rm=.false.)'),
      do.call(fun, list(x, na.rm = FALSE)), paste(nm, fun, 'keepNA'))
  }
  scalar(paste0('gini(', fvec(x), ', corr=.true.)'), Gini(x, corr = TRUE), paste(nm, 'Gini correction'))
  scalar(paste0('var_coeff(', fvec(x), ', square=.true.)'), var.coeff(x, square = TRUE), paste(nm, 'squared CV'))
  for (fun in c('Watts', 'Sen', 'SST', 'Foster')) {
    for (k in c(0, 3, 9)) {
      scalar(paste0(tolower(fun), '(', fvec(x), ', ', fnum(k), ')'),
        suppressWarnings(do.call(fun, list(x, k))), paste(nm, fun, 'k', k))
    }
    if (anyNA(x)) scalar(paste0(tolower(fun), '(', fvec(x), ', 3.0_dp, na_rm=.false.)'),
      do.call(fun, list(x, 3, na.rm = FALSE)), paste(nm, fun, 'keepNA'))
  }
}
for (fun in c('Atkinson', 'Theil', 'Kolm', 'entropy', 'Herfindahl')) {
  for (a in c(-2, -1, 0, 0.5, 1, 2, 3, 1e-6, 0.999999, 1.000001)) {
    for (nm in c('positive', 'zero', 'signed', 'negative')) {
      x <- samples[[nm]]
      scalar(paste0(spec[[fun]], '(', fvec(x), ', parameter=', fnum(a), ')'),
        suppressWarnings(do.call(fun, list(x, parameter = a))), paste(nm, fun, 'a', a))
    }
  }
}
for (a in c(0, 1, 2, 3, 0.5, -1)) scalar(paste0('foster(', fvec(samples$zero), ', 4.0_dp, ', fnum(a), ')'),
  Foster(samples$zero, 4, a), paste('Foster parameter', a))
for (type in c('Gini', 'RS', 'Atkinson', 'Theil', 'Kolm', 'var', 'square.var', 'entropy'))
  scalar(paste0('ineq(', fvec(samples$positive), ", type='", type, "')"),
    ineq(samples$positive, type = type), paste('ineq dispatcher', type))
for (type in c('Herfindahl', 'Rosenbluth')) scalar(paste0('conc(', fvec(samples$positive), ", type='", type, "')"),
  conc(samples$positive, type = type), paste('conc dispatcher', type))
for (type in c('Watts', 'Sen', 'SST', 'Foster')) scalar(paste0('pov(', fvec(samples$positive), ", 4.0_dp, type='", type, "')"),
  pov(samples$positive, 4, type = type), paste('pov dispatcher', type))
for (p in c(0, 1e-10, 1e-6, 0.01, 0.1, 0.5, 0.9, 0.99, 1 - 1e-6, 1 - 1e-10, 1)) {
  for (fun in c('Lc.exp', 'Lc.lognorm', 'Lc.pareto', 'Lc.singh', 'Lc.dagum')) {
    if (fun == 'Lc.exp' && p == 1) next # mathematical endpoint extension is tested separately
    scalar(paste0(gsub('.', '_', tolower(fun), fixed = TRUE), '(', fnum(p), ')'),
      do.call(fun, list(p)), paste(fun, p))
  }
  for (fun in c('Lc.lognorm', 'Lc.pareto')) for (a in c(-2, 0, 0.5, 1, 3.4, 20))
    scalar(paste0(gsub('.', '_', tolower(fun), fixed = TRUE), '(', fnum(p), ', ', fnum(a), ')'),
      suppressWarnings(do.call(fun, list(p, a))), paste(fun, p, 'parameter', a))
  for (fun in c('Lc.singh', 'Lc.dagum')) for (a in list(c(3.4, 2.6), c(1.5, 3), c(0, 0), c(1, 2), c(2), c(2, -3)))
    scalar(paste0(gsub('.', '_', tolower(fun), fixed = TRUE), '(', fnum(p), ', ', fvec(a), ')'),
      suppressWarnings(do.call(fun, list(p, a))), paste(fun, p, 'parameters', paste(a, collapse = ',')))
}
for (type in c('Singh-Maddala', 'Dagum', 'lognorm', 'Pareto', 'exponential'))
  scalar(paste0("theor_lc(0.35_dp, type='", type, "', parameter=[3.4_dp, 2.6_dp])"),
    theorLc(type, c(3.4, 2.6))(0.35), paste('theorLc dispatcher', type))
weighted <- list(
  regular = list(x = c(1, 2, 4, 8), w = c(3, 1, 2, 4)),
  unsorted = list(x = c(8, 1, 4, 2), w = c(4, 3, 2, 1)),
  missing = list(x = c(1, NA, 4, 8), w = c(3, 99, 2, 4)),
  equal = list(x = c(2, 2, 2), w = c(1, 2, 3)),
  tied_mean = list(x = c(1, 2, 3), w = c(1, 1, 1)),
  zeros = list(x = c(0, 1, 4), w = c(2, 0, 3)),
  signed = list(x = c(-2, 1, 4), w = c(2, 1, 3)))
for (nm in names(weighted)) {
  x <- weighted[[nm]]$x
  w <- weighted[[nm]]$w
  ans <- Lc(x, w)
  append(paste0('   curve = lc(', fvec(x), ', ', fvec(w), ')'))
  append(paste0("   call require(curve%status == ineq_ok, 'Lc ", nm, " status')"))
  for (component in names(ans)) {
    target <- c(p = 'p', L = 'l', 'L.general' = 'l_general')[[component]]
    vector(paste0('curve%', target), ans[[component]], paste('Lc', nm, component))
  }
  for (iv in c(FALSE, TRUE)) {
    ans <- tryCatch(Lasym(x, w, interval = iv), error = function(e) NULL)
    if (!is.null(ans)) vector(paste0('lasym(', fvec(x), ', ', fvec(w), ', interval=',
      if (iv) '.true.' else '.false.', ')'), ans, paste('Lasym', nm, 'interval', iv))
  }
}
x <- c(541, 1463, 2445, 3438, 4437, 5401, 6392, 8304, 11904, 22261)
w <- c(482, 825, 722, 690, 661, 760, 745, 2140, 1911, 1024)
for (case in list(list(x = x, w = w), list(x = c(1, 5), w = c(3, 7)),
                 list(x = c(1, 3, 8), w = c(1, 2, 3)))) {
  ans <- Lc.mehran(case$x, case$w)
  append(paste0('   curve = lc_mehran(', fvec(case$x), ', ', fvec(case$w), ')'))
  append("   call require(curve%status == ineq_ok, 'Mehran status')")
  vector('curve%p', ans$p, paste('Mehran', length(case$x), 'p'))
  vector('curve%l', ans$L, paste('Mehran', length(case$x), 'L'))
}
for (case in list(list(x = c(0, 0, 6), y = c(1, 2, 3)), list(x = c(1, 2, 3), y = c(0, 0, 6)),
                 list(x = c(2, NA, 1), y = c(1, 2)))) {
  ans <- major(case$x, case$y)
  append(paste0('   call major(', fvec(case$x), ', ', fvec(case$y), ', dominates, status)'))
  append("   call require(status == ineq_ok, 'major comparable')")
  append(paste0('   call require(dominates .eqv. ', if (ans) '.true.' else '.false.', ", 'major R result')"))
}
append("   if (failed > 0) error stop 1")
append("   print *, 'R reference checks passed:', checked")
append('end program test_r_reference')
writeLines(lines, 'test/test_r_reference.f90')
write.table(do.call(rbind, records), 'validation/R-reference.tsv', sep = '\t', row.names = FALSE, quote = FALSE)
writeLines(capture.output(sessionInfo()), 'validation/R-session-info.txt')
